-- Masking policy: show real email only to COMPLIANCE_ROLE
CREATE MASKING POLICY email_mask AS (val STRING) RETURNS STRING ->
  CASE
    WHEN CURRENT_ROLE() = 'COMPLIANCE_ROLE' THEN val
    ELSE REGEXP_REPLACE(val, '^.+(@.+)$', '***\\1')
  END;

-- Row access policy: restrict to assigned region, with compliance exempt
CREATE ROW ACCESS POLICY region_access AS (region STRING) RETURNS BOOLEAN ->
  CURRENT_ROLE() = 'COMPLIANCE_ROLE'
  OR region = (SELECT assigned_region FROM governance.user_region_map WHERE username = CURRENT_USER());

-- Apply both to the table
ALTER TABLE customers MODIFY COLUMN email SET MASKING POLICY email_mask;
ALTER TABLE customers ADD ROW ACCESS POLICY region_access ON (region);

