def validate_production_promotion(model_metadata: dict) -> tuple[bool, list[str]]:
    """Gate check run by CI/CD before a model can be promoted to 'Production'.
    Returns (is_allowed, list_of_failure_reasons).
    """
    failures = []

    model_card = model_metadata.get("model_card")
    if not model_card or not model_card.get("intended_use"):
        failures.append("Missing or incomplete model card (intended_use required)")

    bias_eval = model_metadata.get("bias_evaluation")
    if not bias_eval:
        failures.append("Missing bias evaluation result")
    elif bias_eval.get("status") != "PASSED":
        failures.append(f"Bias evaluation did not pass (status={bias_eval.get('status')})")
    elif bias_eval.get("age_days", 999) > 90:
        failures.append("Bias evaluation is stale (older than 90 days)")

    owner = model_metadata.get("owner")
    if not owner or owner == model_metadata.get("author"):
        failures.append("Missing named owner, or owner is the same as the model's author")

    return (len(failures) == 0, failures)

-- Create the tag
CREATE TAG IF NOT EXISTS governance.pii_tag
    ALLOWED_VALUES 'EMAIL', 'PHONE', 'SSN';

-- Create the masking policies (one per sensitivity shape, kept simple here)
CREATE MASKING POLICY governance.generic_pii_mask AS (val STRING) RETURNS STRING ->
    CASE WHEN CURRENT_ROLE() IN ('COMPLIANCE_ROLE', 'DATA_GOVERNANCE_ADMIN') THEN val
         ELSE '***MASKED***'
    END;

-- Associate the masking policy with the tag itself
ALTER TAG governance.pii_tag SET MASKING POLICY governance.generic_pii_mask;

-- Apply the tag to a column -- masking now applies automatically
ALTER TABLE customers MODIFY COLUMN phone_number SET TAG governance.pii_tag = 'PHONE';

