CREATE TABLE dbo.DimEmployee (
    EmployeeKey   INT IDENTITY(1,1) PRIMARY KEY CLUSTERED,
    EmployeeID    INT NOT NULL,            -- natural/business key
    EmployeeName  NVARCHAR(100) NOT NULL,
    DepartmentName NVARCHAR(100) NOT NULL,
    Title         NVARCHAR(100) NOT NULL,
    StartDate     DATE NOT NULL,
    EndDate       DATE NULL,
    IsCurrent     BIT NOT NULL DEFAULT 1
);
CREATE UNIQUE NONCLUSTERED INDEX IX_DimEmployee_BusinessKey_Effective
ON dbo.DimEmployee (EmployeeID, StartDate);

CREATE TABLE dbo.FactEmployeePerformance (
    EmployeePerformanceKey BIGINT IDENTITY(1,1) PRIMARY KEY CLUSTERED,
    EmployeeKey   INT NOT NULL REFERENCES dbo.DimEmployee(EmployeeKey),
    ReviewDateKey INT NOT NULL REFERENCES dbo.DimDate(DateKey),
    PerformanceScore DECIMAL(5,2) NOT NULL
);
CREATE NONCLUSTERED INDEX IX_FactEmployeePerformance_EmployeeKey ON dbo.FactEmployeePerformance (EmployeeKey);
CREATE NONCLUSTERED INDEX IX_FactEmployeePerformance_ReviewDateKey ON dbo.FactEmployeePerformance (ReviewDateKey);
